checkpoint={'recorded_at':now(),'company_id':'jp:5831','issue_id':'5831-financial-equity-model-inputs','scope':'Initial four-page issuer financial-structure review, after-source-save binding checkpoint; not an investment business thesis or source meaning certification.','review_path':str((OUT/'review.json').relative_to(ROOT)),'review_sha256':sha256((OUT/'review.json').read_bytes()).hexdigest(),'source_bindings':[{'source_id':s['id'],'source_snapshot_sha256':sha256(json_text(s).encode()).hexdigest()} for s in sources],'future_regulatory_capital_and_model_inputs_unverified':True,'independent_semantic_review_completed':False};save('review-binding-checkpoint.json',checkpoint)
