request={'case_id':'5831-financial-structure-monitor','company_id':'jp:5831','issue_id':'5831-financial-equity-model-inputs','synthetic':False,'enabled':True,'recorded_at':now(),'case_ref':ref('model-routing-assessment.json'),'manifest_ref':ref('review-binding-checkpoint.json'),'management_review':None,'bootstrap_reviews':[{'source_id':item['source_id'],'source_snapshot_sha256':item['source_snapshot_sha256'],'reviewed_at':now(),'review_ref':ref('review-binding-checkpoint.json')} for item in checkpoint['source_bindings']]};save('case-register-input.json',request);q=QualitativeResearch(store);save('case-registered.json',q.register_case(request,research_root=ROOT));current=datetime.now(timezone.utc);queued=q.queue_cases([request['case_id']],current.isoformat(),now=current);save('case-post-bootstrap-queue.json',queued);assert queued['jobs_created']==0
unchanged={}
for table,rows in before.items():
 after={tuple(r) for r in store.connection.execute('select * from '+table)};unchanged[table]=all(tuple(r) in after for r in rows);assert unchanged[table]
